function structuredPhraseToBody(p) {
  const lines = [p.assessment];
  if (p.workup && p.workup.length) {
    lines.push('Workup:');
    p.workup.forEach(w => lines.push('- ' + w));
  }
  if (p.plan && p.plan.length) {
    if ((p.workup && p.workup.length) || p.redFlags) lines.push('Plan:');
    p.plan.forEach(pl => lines.push('- ' + pl));
  }
  if (p.redFlags) lines.push('Disposition/red flags: ' + p.redFlags);
  return lines.join('\n');
}

const BUILTIN_DOTPHRASES = DOTPHRASE_STRUCTURED_DATA.phrases.map(p => ({
  id: p.id,
  trigger: '.' + p.trigger.replace(/^\./, ''),
  title: p.title,
  category: p.category,
  body: structuredPhraseToBody(p),
  structured: p
}));
